package android.graphics;
public final class Bitmap { public enum Config { ALPHA_8,RGB_565,ARGB_4444,ARGB_8888,HARDWARE } private final int w,h; private int[] pixels; private int resource; private boolean recycled; Bitmap(int w,int h,int r){if(w<=0||h<=0)throw new IllegalArgumentException();this.w=w;this.h=h;resource=r;pixels=new int[w*h];} public static Bitmap createBitmap(int w,int h,Config c){return new Bitmap(w,h,0);} public static Bitmap createBitmap(Picture p){return new Bitmap(Math.max(1,p.getWidth()),Math.max(1,p.getHeight()),0);} public static Bitmap createBitmap(Bitmap b){Bitmap n=new Bitmap(b.w,b.h,b.resource);for(int i=0;i<b.pixels.length;i++)n.pixels[i]=b.pixels[i];return n;} public int getWidth(){return w;} public int getHeight(){return h;} public void recycle(){recycled=true;} public boolean isRecycled(){return recycled;} public void eraseColor(int c){for(int i=0;i<pixels.length;i++)pixels[i]=c;} public int getPixel(int x,int y){return pixels[y*w+x];} public void setPixel(int x,int y,int c){pixels[y*w+x]=c;} public int indroidResource(){return resource;} }